import{z as i,x as p,o as l,c as A,q as n,j as E,D as r,d as o,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"自然循环识别","description":"","frontmatter":{"title":"自然循环识别","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/natural-loops.md","filePath":"cs/natural-loops.md","lastUpdated":1791413859000}'),B={name:"cs/natural-loops.md"};function h(D,a,c,m,u,f){const t=p("Mermaid");return l(),A("div",null,[a[2]||(a[2]=n('<h1 id="自然循环识别" tabindex="-1">自然循环识别 <a class="header-anchor" href="#自然循环识别" aria-label="Permalink to &quot;自然循环识别&quot;">​</a></h1><div class="epigraph"><p>回边的头支配尾。自然循环是头加上不经过头而能到达该回边尾的节点。嵌套由头的包含关系给出。</p><footer>—— 据龙书 9.6；Muchnick；Tarjan 区间分析对照整理</footer></div><p>上一课<a href="/cs/polyhedral-model">多面体</a>用统一代数改写仿射循环，前提是先认出循环。LICM、IV、展开都要<strong>循环对象</strong>。主干 CFG 课有块与边。缺口是<strong>自然循环</strong>：从回边识别头与体。不可约 CFG 没有整齐的自然循环树，要先变换或放弃部分循环优化。本课钉定义，不写 PGO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回边：尾到头，且头支配尾。自然循环：体是所有「不经头能到尾」的节点加头。缺口是<strong>嵌套森林</strong>，不是 φ 放置。</p><p><span class="marginnote">术语翻译：「支配」就是「必经」——从入口到 n 不管怎么绕都躲不开 d，就记作 d 支配 n。回边要求「头支配尾」，翻译成大白话：想走这条回头路，必然先路过 h，所以 h 是这个圈唯一的门口，进出都得打招呼。</span></p><p>前置头：造一个唯一外入块，方便 LICM。不可约：两个入口，无单一头，自然循环定义失败。</p><h3 id="自然循环不是「源码的-for」" tabindex="-1">自然循环不是「源码的 for」 <a class="header-anchor" href="#自然循环不是「源码的-for」" aria-label="Permalink to &quot;自然循环不是「源码的 for」&quot;">​</a></h3><p><code>goto</code> 可造不可约。识别结果可能与程序员写的 <code>for</code> 不同（多个 break）。优化认的是 CFG 循环，不是 AST 循环——除非前端保留元数据。</p><p><span class="marginnote">常见误区：初学者以为「循环就是源码里的 for」。编译器只认 CFG 上的回边：<code>goto</code> 能拼出两个互相进入、谁也不支配谁的怪圈（不可约，连唯一的头都没有）；带多个 <code>break</code> 的 <code>for</code> 也会被识别成多出口循环——识别结果与关键字无关。</span></p><p><span class="marginnote">龙书循环。Havlak 不可约循环。LLVM LoopInfo。本课以可约为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算支配。找回边。对每条回边扩体（反向 CFG 搜索）。按头支配关系建嵌套。插入 preheader。</p>',13)),(l(),E(d,null,{default:r(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E6%94%AF%E9%85%8D%22%5D%20--%3E%20BE%5B%22%E5%9B%9E%E8%BE%B9%22%5D%0A%20%20BE%20--%3E%20BODY%5B%22%E8%87%AA%E7%84%B6%E5%BE%AA%E7%8E%AF%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20PH%5B%22%E5%89%8D%E7%BD%AE%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与多面体：SCoP 检测也要循环树。与向量化：最内自然循环是候选。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[o("开关与多出口：循环仍自然，只是退出边多，LICM 安全条件更严。不要把 "),e("code",null,"do-while"),o(" 当没有 preheader 就不能优化——可以造。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：扩体像从回边倒着灌水找湖的范围——水从尾节点倒灌，凡是「不经过头（门口）」就能流到尾的房间都会被淹到；淹到的房间合起来就是循环体。门口 h 本身也算一间。")],-1)),a[7]||(a[7]=e("p",null,"深度：内层先处理是 LICM/IV 的标准序。",-1)),(l(),E(d,null,{default:r(()=>[s(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20BE%5B%22%E5%9B%9E%E8%BE%B9%20n%20%E2%86%92%20h%EF%BC%88h%20%E6%94%AF%E9%85%8D%20n%EF%BC%89%22%5D%20--%3E%20INIT%5B%22body%20%3D%20%7Bh%2C%20n%7D%EF%BC%8Cn%20%E5%85%A5%E5%B7%A5%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20INIT%20--%3E%20POP%5B%22%E5%8F%96%E5%87%BA%E8%8A%82%E7%82%B9%20m%22%5D%0A%20%20POP%20--%3E%20PRED%5B%22%E9%81%8D%E5%8E%86%20m%20%E7%9A%84%E5%89%8D%E9%A9%B1%20p%22%5D%0A%20%20PRED%20--%3E%20INS%5B%22p%20%E4%B8%8D%E5%9C%A8%20body%EF%BC%9A%E5%8A%A0%E5%85%A5%E5%B9%B6%E5%85%A5%E6%A0%88%22%5D%0A%20%20INS%20--%3E%20POP%0A%20%20POP%20--%3E%7C%22%E5%B7%A5%E4%BD%9C%E8%A1%A8%E7%A9%BA%22%7C%20DONE%5B%22%E4%BD%93%E7%A1%AE%E5%AE%9A%EF%BC%9A%E5%A4%B4%20h%20%E5%8A%A0%E5%85%A8%E4%BD%93%E5%8F%AF%E8%BE%BE%E5%89%8D%E9%A9%B1%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部不可约变换（节点分裂）。后课默认：可约 CFG 有循环树。后课 PGO 会用轮廓给循环行程与分支概率，驱动展开与内联。下一课<a href="/cs/alias-analysis">别名分析</a>：循环内的访存优化要先回答是否同一对象。</p><p>也不把自然循环当链表上的「环检测」算法课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回边 + 支配 ⇒ 自然循环；嵌套成树。</li><li>preheader 服务外提。</li><li>不可约要另处理。</li><li>出处：Aho et al. 龙书 9.6；Muchnick；对照 Tarjan 区间。</li></ul>',5))])}const b=i(B,[["render",h]]);export{P as __pageData,b as default};
